package com.alpharip.staffmod.BuildTimelapse.effects; public final class EffectsController {private final EffectsRuntimePort port;private final VisualEffectsProfile profile;public EffectsController(EffectsRuntimePort p,VisualEffectsProfile v){if(p==null||v==null)throw new IllegalArgumentException();port=p;profile=v;}public VisualEffectsProfile getProfile(){return profile;}public void setTime(long t)throws Exception{port.setWorldTime(t);}public void setWeather(String w,float s)throws Exception{port.setWeather(w,s);}public void applyHud()throws Exception{port.setHudVisible(!profile.isHideHud());}public void restore()throws Exception{port.restoreOriginalSettings();}}
